5	const NO_REPLY = 'Could not reach the server.';
6	const FAILED = 'Request failed.';
7	
8	const bk = (id, room, title, date = '2026-11-03', start = '09:00', end = '10:00') =>
9	  ({ id, room, title, date, start, end });
10	const A1 = bk(1, 'Aurora', 'Standup');
11	const B1 = bk(2, 'Borealis', 'Review', '2026-11-04', '11:00', '12:30');
12	const C1 = bk(3, 'Cosmos', 'Retro', '2026-11-05', '08:00', '08:30');
