16	/** Loads the app and answers rooms and the first list fetch. */
17	async function boot({ rooms = ['Aurora', 'Borealis', 'Cosmos'], bookings = [] } = {}) {
18	  const page = loadApp();
19	  roomsCall(page).reply(200, { rooms });
20	  page.listFetches()[0].reply(200, { bookings });
21	  await flush();
22	  return page;
23	}
