36	/** Boots with a rendered list, then starts a refetch via change. */
37	async function bootWithList() {
38	  const page = await boot({ bookings: [A1, B1] });
39	  const before = [...listItems(page)];
40	  page.el('filter-date').dispatch('change');
41	  return { page, before, refetch: page.lastFetch() };
