1	// public/app.js booking submit and cancel flows, run in the fake browser.
2	import assert from 'node:assert/strict';
3	import { test } from 'node:test';
4	import { flush, loadApp } from './helpers/fake-dom.mjs';
5	
6	const ROOMS = { rooms: ['Aurora', 'Borealis', 'Cosmos'] };
7	const B7 = { id: 7, room: 'Aurora', title: 'Alpha', date: '2026-11-03', start: '09:00', end: '10:00' };
8	const B12 = { id: 12, room: 'Cosmos', title: 'Beta', date: '2026-11-04', start: '11:00', end: '12:00' };
9	const NO_REPLY = 'Could not reach the server.';
10	const FAILED = 'Request failed.';
11	const CONFLICT = 'room is already booked from 09:00 to 10:00';
12	const VALUES = { room: 'Borealis', title: '  Team  sync ', date: '2026-11-3', start: '9:00', end: '' };
13	
14	async function boot(bookings = []) {
15	  const page = loadApp();
16	  page.fetches[0].reply(200, ROOMS);
17	  page.fetches[1].reply(200, { bookings });
18	  await flush();
19	  return page;
20	}
21	
22	function fillForm(page, values = VALUES) {
23	  for (const [id, v] of Object.entries(values)) page.el(id).value = v;
24	}
25	
26	const cancelButton = (page, index) => page.el('booking-list').children[index].children[0];
27	const submit = (page) => page.el('booking-form').dispatch('submit');
28	const errorText = (page) => page.el('error').textContent;
29	const formValues = (page) => Object.fromEntries(Object.keys(VALUES).map((k) => [k, page.el(k).value]));
30	
31	/** Submits and returns the POST call. */
32	function startSubmit(page) {
33	  const before = page.fetches.length;
34	  submit(page);
35	  assert.strictEqual(page.fetches.length, before + 1);
36	  return page.lastFetch();
37	}
38	
39	/** Boots, fills the form, and shows `message` in #error through a 409 submit. */
40	async function bootWithError(bookings, message = CONFLICT) {
41	  const page = await boot(bookings);
42	  fillForm(page);
43	  startSubmit(page).reply(409, { error: message });
44	  await flush();
45	  assert.strictEqual(errorText(page), message);
46	  return page;
47	}
48	
49	const SETTLERS = {
50	  'reply 201': (call) => call.reply(201, B7),
51	  'reply 409': (call) => call.reply(409, { error: CONFLICT }),
52	  'fail()': (call) => call.fail(),
53	  'replyNotJson(201)': (call) => call.replyNotJson(201),
54	};
55	
56	test('submit sends the exact POST request and disables Book', async () => {
57	  const page = await boot();
58	  fillForm(page);
59	  const before = page.fetches.length;
60	  const event = submit(page);
61	  assert.strictEqual(event.preventDefaultCalls, 1);
62	  assert.strictEqual(page.fetches.length, before + 1);
63	  const call = page.lastFetch();
64	  assert.strictEqual(call.url, '/api/bookings');
65	  assert.deepStrictEqual(Object.keys(call.options).sort(), ['body', 'headers', 'method']);
66	  assert.strictEqual(call.method, 'POST');
67	  // Entries: the headers object comes from the vm realm, so its prototype differs.
68	  assert.deepStrictEqual(Object.entries(call.options.headers), [['Content-Type', 'application/json']]);
69	  assert.deepStrictEqual(JSON.parse(call.options.body), VALUES);
70	  assert.strictEqual(page.el('book').disabled, true);
71	  assert.deepStrictEqual(page.violations, []);
72	});
73	
74	test('second submit while pending is prevented and sends nothing', async () => {
75	  const page = await boot();
76	  fillForm(page);
77	  startSubmit(page);
78	  const count = page.fetches.length;
79	  const event = submit(page);
80	  assert.strictEqual(event.preventDefaultCalls, 1);
81	  assert.strictEqual(page.fetches.length, count);
82	  assert.deepStrictEqual(page.violations, []);
83	});
84	
85	test('submit with Book disabled by the test sends nothing', async () => {
86	  const page = await boot();
87	  fillForm(page);
88	  page.el('book').disabled = true;
89	  const count = page.fetches.length;
90	  const event = submit(page);
91	  assert.strictEqual(event.preventDefaultCalls, 1);
92	  assert.strictEqual(page.fetches.length, count);
93	  assert.deepStrictEqual(page.violations, []);
94	});
