96	for (const [name, settle] of Object.entries(SETTLERS)) {
97	  test(`Book is enabled first when the request settles: ${name}`, async () => {
98	    const page = await boot();
99	    fillForm(page);
100	    const call = startSubmit(page);
101	    const index = page.log.length;
102	    settle(call);
103	    await flush();
104	    const after = page.log.slice(index).filter((entry) => !entry.startsWith('response.'));
105	    assert.strictEqual(after[0], '#book.disabled=false');
106	    assert.strictEqual(page.el('book').disabled, false);
107	    assert.deepStrictEqual(page.violations, []);
108	  });
109	}
