123	test('201 empties title and error, keeps other values, refetches the filtered list', async () => {
124	  const page = await bootWithError([B7]);
125	  page.el('filter-date').value = '2026-11-03';
126	  const lists = page.listFetches().length;
127	  startSubmit(page).reply(201, B7);
128	  await flush();
129	  assert.strictEqual(page.el('title').value, '');
130	  assert.deepStrictEqual(formValues(page), { ...VALUES, title: '' });
131	  assert.strictEqual(errorText(page), '');
132	  assert.strictEqual(page.listFetches().length, lists + 1);
133	  assert.strictEqual(page.lastFetch().url, '/api/bookings?date=2026-11-03');
134	  assert.deepStrictEqual(page.violations, []);
135	});
