137	const ERROR_CASES = [
138	  ['409 error message', 409, { error: CONFLICT }, CONFLICT],
139	  ['400 error message', 400, { error: 'title must be 1 to 80 characters' }, 'title must be 1 to 80 characters'],
140	  ['500 error message', 500, { error: 'internal error' }, 'internal error'],
141	  ['200 instead of 201', 200, { id: 1, ...B7 }, FAILED],
142	  ['415 non-string error', 415, { error: 1 }, FAILED],
143	  ['400 array body', 400, [], FAILED],
144	];
145	
146	for (const [name, status, body, expected] of ERROR_CASES) {
147	  test(`submit error status: ${name}`, async () => {
148	    const page = await boot([B7, B12]);
